insert into submissions (id, submitted_at, form_data, status, owner_email, business_unit)
values ('seed-uspto-sub-teas', now() - interval '30 hours', '{"submitterName": "USPTO Submitter", "submitterEmail": "submitter@uspto.gov", "submitterRole": "it_staff", "submitterOffice": "trademarks", "publicIndicator": "public", "targetAudience": "other", "assignedReviewerName": "Matt Shankle", "assignedReviewerEmail": "matt.shankle@uspto.gov", "useCaseTitle": "Automated TEAS Submission Validator", "useCaseDescription": "A pre-submission validator that flags likely errors and missing items in a trademark e-filing before it is filed, so applicants fix them up front.", "coreProblem": "Trademark e-filings come in with avoidable errors (wrong class, bad specimen, missing fields) that bounce back and add pendency and examiner rework.", "problemImpact": "Avoidable filing errors drive office actions and rework, lengthening trademark pendency.", "impactedUsersCount": "gt_500", "proposedSolution": "Validation model that checks a draft TEAS submission against common error patterns and class rules and flags issues with an explanation; applicant corrects and files clean.", "businessValue": "Fewer rejected or deficient filings, less examiner rework, lower pendency.", "costSavings": "250k_1m", "usptoFocusArea": ["goal_pendency_quality"], "successMetrics": "Filing error rate; office actions tied to filing defects; examiner rework hours.", "timelineForResults": "6_12", "implementationComplexity": "medium", "involvesSensitiveData": "no", "aiModelSourcing": "open_source_us", "aiDecisionalImpact": "no", "aiHumanReview": "yes", "readinessScore": "ready", "readinessSummary": "Strong pendency-and-quality case with a clear measurable outcome. Examiner-in-the-loop; American-built/open-source U.S.-hosted model.", "executiveSummary": "Trademark e-filings arrive with avoidable errors that bounce back and add pendency. A pre-submission validator flags likely errors and missing items so applicants file clean. Directly supports pendency and quality, with a measurable error-rate outcome.", "reviewStatus": "submitted"}'::jsonb, 'submitted', 'submitter@uspto.gov', 'trademarks')
on conflict (id) do nothing;

insert into submissions (id, submitted_at, form_data, status, owner_email, business_unit)
