insert into submissions (id, submitted_at, form_data, status, owner_email, business_unit)
values ('seed-uspto-sub-idmanual', now() - interval '120 hours', '{"submitterName": "USPTO Submitter", "submitterEmail": "submitter@uspto.gov", "submitterRole": "it_staff", "submitterOffice": "trademarks", "publicIndicator": "public", "targetAudience": "other", "assignedReviewerName": "Matt Shankle", "assignedReviewerEmail": "matt.shankle@uspto.gov", "useCaseTitle": "Trademark ID Manual Smart Search", "useCaseDescription": "Semantic search over the Acceptable Identification of Goods and Services Manual that returns ranked suggested identifications with class for an examiner or applicant to pick.", "coreProblem": "Examiners and applicants struggle to find the right entries in the ID Manual with keyword search, leading to inconsistent identifications.", "problemImpact": "Hard-to-search IDs cause inconsistent identifications and identification-related office actions.", "impactedUsersCount": "50_500", "proposedSolution": "Embedding-based search over the ID Manual returning ranked suggested IDs with class; the user selects. No automated determination.", "businessValue": "Faster, more consistent ID selection; fewer office actions tied to identification.", "costSavings": "50k_250k", "usptoFocusArea": ["goal_pendency_quality"], "successMetrics": "Time to select an ID; identification-related office action rate; suggestion acceptance rate.", "timelineForResults": "3_6", "implementationComplexity": "low", "involvesSensitiveData": "no", "aiModelSourcing": "open_source_us", "aiDecisionalImpact": "no", "aiHumanReview": "yes", "readinessScore": "ready", "readinessSummary": "Low-risk, well-scoped, measurable, American-built/open-source U.S.-hosted, user-in-the-loop. Approved.", "executiveSummary": "Keyword search over the Trademark ID Manual makes the right identifications hard to find, driving inconsistency. Semantic search returns ranked suggested IDs for the user to pick. Low risk, measurable, examiner-in-the-loop.", "reviewStatus": "approved"}'::jsonb, 'approved', 'submitter@uspto.gov', 'trademarks')
on conflict (id) do nothing;
